_ED_P = 2 ** 255 - 19
_ED_Q = 2 ** 252 + 27742317777372353535851937790883648493
_ED_D = -121665 * pow(121666, _ED_P - 2, _ED_P) % _ED_P
_ED_I = pow(2, (_ED_P - 1) // 4, _ED_P)


def _ed_add(a, b):
    (x1, y1), (x2, y2) = a, b
    t = _ED_D * x1 * x2 * y1 * y2 % _ED_P
    return ((x1 * y2 + x2 * y1) * pow(1 + t, _ED_P - 2, _ED_P) % _ED_P,
            (y1 * y2 + x1 * x2) * pow(1 - t, _ED_P - 2, _ED_P) % _ED_P)


def _ed_mul(pt, e):
    r, q = (0, 1), pt
    while e:
        if e & 1:
            r = _ed_add(r, q)
        q = _ed_add(q, q)
        e >>= 1
    return r


def _ed_point(b32):
    y = int.from_bytes(b32, "little")
    sign, y = y >> 255, y & ((1 << 255) - 1)
    if y >= _ED_P:
        return None
    xx = (y * y - 1) * pow(_ED_D * y * y + 1, _ED_P - 2, _ED_P) % _ED_P
    x = pow(xx, (_ED_P + 3) // 8, _ED_P)
    if (x * x - xx) % _ED_P:
        x = x * _ED_I % _ED_P
    if (x * x - xx) % _ED_P:
        return None
    if x & 1 != sign:
        x = _ED_P - x
    return (x, y)


_ED_B = (15112221349535400772501151409588531511454012693041857206046113283949847762202,
         46316835694926478169428394003475163141307993866256225615783033603165251855960)


def _ed25519_verify(pub, sig, msg):
    import hashlib
    try:
        if len(pub) != 32 or len(sig) != 64:
            return False
        a, r = _ed_point(pub), _ed_point(sig[:32])
        s_ = int.from_bytes(sig[32:], "little")
        if a is None or r is None or s_ >= _ED_Q:
            return False
        h = int.from_bytes(hashlib.sha512(sig[:32] + pub + msg).digest(), "little") % _ED_Q
        return _ed_mul(_ED_B, s_) == _ed_add(r, _ed_mul(a, h))
    except Exception:
        return False


def _vt(v):
    try:
        return tuple(int(x) for x in str(v).split("."))
    except Exception:
        return (0,)


def _update():
    if globals().get("_SKIP_UPDATE") or os.environ.get("ABA_NO_UPDATE"):
        return False
    try:
        import json, time, urllib.request
        def get(name, limit):
            req = urllib.request.Request(_UPD_BASE + name + "?t=" + str(int(time.time())), headers={"User-Agent": "ABA-Timer"})
            with urllib.request.urlopen(req, timeout=5) as r:
                data = r.read(limit + 1)
            if len(data) > limit:
                raise ValueError("too big")
            return data
        man = json.loads(get("version.json", 20000).decode("utf-8"))
        ver, files = str(man["version"]), dict(man["files"])
        if _vt(ver) <= _vt(_LV):
            return False
        if set(files) - {"ABA_Timer.py", "hotbar_profiles.npz"} or "ABA_Timer.py" not in files:
            return False
        msg = ("ABAUPD1\n" + ver + "\n" + "\n".join(n + "=" + files[n] for n in sorted(files))).encode()
        if not _ed25519_verify(base64.b64decode(_UPD_PUB), base64.b64decode(man["sig"]), msg):
            return False
        print("ABA Timer: updating " + _LV + " -> " + ver + " ...", flush=True)
        here = os.path.dirname(os.path.abspath(__file__))
        me = os.path.abspath(__file__)
        new = {}
        for n, h in files.items():
            data = get(n, 20000000)
            if hashlib.sha256(data).hexdigest() != h:
                return False
            new[n] = data
        if ('_LV = "' + ver + '"').encode() not in new["ABA_Timer.py"]:
            return False
        compile(new["ABA_Timer.py"], "ABA_Timer.py", "exec")
        done = []
        try:
            for n, data in new.items():
                path = me if n == "ABA_Timer.py" else os.path.join(here, n)
                if os.path.exists(path):
                    try:
                        import shutil
                        shutil.copyfile(path, path + ".bak")
                    except Exception:
                        pass
                with open(path + ".new", "wb") as f:
                    f.write(data)
                os.replace(path + ".new", path)
                done.append(path)
        except Exception:
            for path in done:
                try:
                    os.replace(path + ".bak", path)
                except Exception:
                    pass
            return False
        print("ABA Timer: updated to " + ver, flush=True)
        return True
    except Exception:
        return False


def _fail(text):
    try:
        import ctypes
        ctypes.windll.user32.MessageBoxW(0, text, "ABA Timer", 0x10)
    except Exception:
        print(text)
    sys.exit(1)


def _ensure_libs():
    import importlib.util
    need = {"numpy": "numpy", "cv2": "opencv-python", "mss": "mss", "dxcam": "dxcam"}
    def missing():
        return [p for m, p in need.items() if importlib.util.find_spec(m) is None]
    if not missing():
        return
    print("ABA Timer: installing the required libraries (first time only, about 150 MB, needs internet)...", flush=True)
    import subprocess
    subprocess.call([sys.executable, "-m", "pip", "install", "--disable-pip-version-check"] + list(need.values()))
    left = missing()
    if left:
        _fail("Could not install: " + ", ".join(left) + ".\nCheck your internet and try again, or open Command Prompt and run:\npip install numpy opencv-python mss dxcam")


def _load():
    v = "%d.%d" % sys.version_info[:2]
    if v not in _B:
        _fail("This program needs Python 3.11, 3.12 or 3.13 (64-bit).\nYou have Python " + v + ".\nInstall one of them from python.org, then open this file again.")
    if sys.gettrace() is not None or sys.getprofile() is not None:
        _fail("Debuggers and tracers are not allowed.")
    k = hashlib.sha256("".join(_P).encode()).digest()
    raw = base64.b85decode(_B[v])
    nonce, tag, ct = raw[:16], raw[16:32], raw[32:]
    if hashlib.sha256(k + nonce + ct).digest()[:16] != tag:
        _fail("This file is damaged. Download the program again.")
    ks, i = [], 0
    while len(ks) * 32 < len(ct):
        ks.append(hashlib.sha256(k + nonce + i.to_bytes(8, "big")).digest())
        i += 1
    ks = b"".join(ks)[:len(ct)]
    code = marshal.loads(zlib.decompress((int.from_bytes(ct, "big") ^ int.from_bytes(ks, "big")).to_bytes(len(ct), "big")))
    return code


def run(name="__main__"):
    g = {"__name__": name, "__file__": os.path.abspath(__file__), "__builtins__": __builtins__, "__doc__": None}
    code = _load()
    _ensure_libs()
    exec(code, g)
    return g


if __name__ == "__main__":
    if _update():
        import runpy
        runpy.run_path(os.path.abspath(__file__), init_globals={"_SKIP_UPDATE": True}, run_name="__main__")
    else:
        run()
